```javascript
const seats = { A: 5, B: 3, C: 3 };
const threshold = 6;
const groups = Object.keys(seats);
const subsets = [];
for (let mask = 1; mask < (1 << groups.length); mask++) {
  subsets.push(groups.filter((_, i) => mask & (1 << i)));
}
const winning = subsets.filter((s) => s.reduce((sum, g) => sum + seats[g], 0) >= threshold);
const minimal = winning.filter((s) => s.every((g) => {
  const without = s.filter((x) => x !== g);
  return without.reduce((a, x) => a + seats[x], 0) < threshold;
}));
return minimal.map((s) => `{${s.join(",")}}`).join(", ");
```

